INSERT INTO `adv_package_addons` (`id`, `tenant_id`, `package_id`, `title`, `description`, `price`, `is_free`, `context_description`, `ai_summary`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(10, 11, 14, 'Sewa Drone DJI Mini 3', 'Dokumentasi aerial profesional sepanjang trip menggunakan Drone DJI Mini 3 Pro. Diterbangkan langsung oleh pilot bersertifikat BSKAI. Hasil dokumentasi berupa 50+ foto aerial resolusi tinggi dan 3 buah video cinematic resolusi 4K yang sudah diedit. Baterai cadangan sudah tersedia sehingga siap merekam momen kapan saja.', 500000.00, 0, NULL, '', 1, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28'),
(11, 11, 14, 'Upgrade Hotel Bintang 5', 'Upgrade akomodasi Anda dari hotel bintang 3 menjadi hotel bintang 5 (Pilihan: The Mulia Bali, Ayana Resort, atau hotel setara). Harga sudah termasuk fasilitas sarapan pagi (breakfast buffet internasional) sepuasnya dan bebas akses ke seluruh fasilitas eksklusif hotel seperti spa, gym, dan private beach.', 1500000.00, 0, NULL, '', 2, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28'),
(12, 11, 15, 'Fotografer Profesional', 'Layanan fotografer profesional yang akan mendampingi Anda selama trip Bromo dan Ijen. Fotografer menggunakan kamera mirrorless Sony A7IV berkualitas tinggi. Anda akan mendapatkan lebih dari 100 foto yang sudah melewati proses editing warna dan pencahayaan (dikirim dalam 3 hari kerja via link Google Drive). Bonus tambahan: Anda juga akan mendapatkan 5 lembar foto yang dicetak langsung di ukuran 4R secara gratis sebagai kenang-kenangan.', 750000.00, 0, '', '', 1, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28');

