INSERT INTO `adv_package_sub_items` (`id`, `tenant_id`, `package_id`, `title`, `description`, `price`, `sort_order`, `slot_mode`, `slot_daily`, `slot_total`, `slot_used_total`, `status`, `created_at`, `updated_at`, `availability_type`, `ai_summary`, `context_description`, `custom_prices`, `include_travel_cost`, `travel_cost_context`) VALUES
(27, 11, 16, 'Backpacker', 'Opsi Backpacker: Akomodasi menggunakan shared cabin (kabin berbagi yang diisi oleh 4 orang per kabin). Sangat cocok bagi budget traveler atau solo traveler yang ingin mencari teman baru. Harga sudah termasuk makan 3 kali sehari dengan menu masakan Indonesia rumahan, peminjaman alat snorkeling standar (masker & snorkel), dan didampingi guide lokal berbahasa Indonesia.', 3500000.00, 0, 'configured', 15, NULL, 0, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28', 'configured', '', '', 'null', 0, NULL),
(28, 11, 16, 'Premium', 'Opsi Premium: Akomodasi eksklusif menggunakan private cabin (1 kabin hanya untuk 2 orang, ideal untuk pasangan atau honeymoon). Fasilitas ditingkatkan dengan menu makan premium (fusion masakan Indonesia-Western), alat snorkeling kualitas profesional (merk Cressi) yang lebih nyaman, welcome drink saat kedatangan, dan pelayanan guide bilingual yang ramah.', 6000000.00, 1, 'configured', 4, NULL, 0, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28', 'confirmation_required', '', '', 'null', 0, NULL),
(29, 11, 16, 'Exclusive Full Charter', 'Opsi Exclusive Full Charter: Sewa penuh 1 kapal phinisi mewah secara private khusus untuk rombongan Anda (maksimal kapasitas 12 orang). Harga yang tercantum adalah harga all-inclusive untuk satu kapal penuh. Anda bebas merancang custom menu makanan dengan private chef, rute destinasi yang fleksibel, waktu snorkeling atau diving (bagi yang bersertifikat) sepuasnya tanpa batasan waktu, serta free dekorasi khusus untuk merayakan honeymoon atau anniversary di atas kapal.', 45000000.00, 2, 'always_ask_admin', 1, 2, 0, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28', 'configured', '', '', 'null', 0, NULL),
(30, 11, 17, 'Honda Vario 125', 'Unit Honda Vario berkapasitas mesin 125 CC. Motor ini sangat hemat bahan bakar (irit bensin), bodinya yang ringan membuatnya sangat lincah untuk menyalip kemacetan kota, cocok digunakan oleh pemula maupun untuk keperluan jalan-jalan santai jarak dekat. Memiliki kapasitas tangki bensin 5.5 Liter.', 75000.00, 1, 'configured', 5, NULL, 0, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28', 'inherit', '', '', NULL, 0, NULL),
(31, 11, 17, 'Honda PCX 160', 'Unit Honda PCX berkapasitas mesin 160 CC. Tergolong motor matic premium dengan desain elegan dan suspensi yang sangat empuk. Dilengkapi dengan kapasitas bagasi super besar (30 Liter) yang bisa menampung banyak barang belanjaan, serta USB charger di dashboard. Sangat stabil dan nyaman digunakan untuk perjalanan jarak jauh (touring) melintasi kabupaten.', 120000.00, 2, 'configured', 3, NULL, 0, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28', 'inherit', '', '', NULL, 0, NULL),
(32, 11, 17, 'Yamaha NMAX 155', 'Unit Yamaha NMAX berkapasitas mesin 155 CC. Motor tipe sport-matic dengan posisi berkendara rileks yang disukai turis asing. Mesin ini dilengkapi teknologi VVA sehingga tarikannya sangat bertenaga besar, serta sistem pengereman ABS untuk keamanan. Sangat tangguh dan cocok digunakan untuk touring menanjak curam ke area pegunungan di Bali, seperti kawasan Kintamani atau Bedugul.', 130000.00, 3, 'configured', 2, NULL, 0, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28', 'inherit', '', '', NULL, 0, NULL),
(41, 11, 14, 'Reguler', 'Pilihan Reguler: Menggunakan akomodasi hotel bintang 3 yang nyaman di area Kuta/Legian. Transportasi menggunakan mobil Avanza atau Innova full AC. Termasuk makan 3x sehari di restoran lokal pilihan, dan didampingi oleh guide profesional berbahasa Indonesia yang ramah.', 3200000.00, 0, 'inherit', NULL, NULL, 0, 'active', '2026-05-27 14:34:47', '2026-05-27 14:34:47', 'inherit', NULL, NULL, '[{\"label\":\"Harga pax anak anak\",\"price\":\"3000000\",\"include_travel_cost\":true,\"travel_cost_context\":\"include biaya perjalanan dari jakarta ke bali, untuk biaya ke jakarta di tanggung sendiri. jika mau langsung ke bali sendiri maka biaya bisa dikurangi 1 juta\"}]', 1, 'include biaya perjalanan dari jakarta ke bali, untuk biaya ke jakarta di tanggung sendiri. jika mau langsung ke bali sendiri maka biaya bisa dikurangi 1,2 juta'),
(42, 11, 14, 'VVIP Experience', 'Pilihan VVIP Premium: Menginap di Private Villa mewah dengan infinity pool di Seminyak. Perjalanan ke Nusa Penida menggunakan speed boat eksklusif (bukan kapal umum). Termasuk private guide bilingual (Inggris-Indonesia), layanan priority booking di semua destinasi, dan pengalaman fine dining romantis di restoran bintang lima pada malam terakhir.', 10000000.00, 1, 'inherit', NULL, NULL, 0, 'active', '2026-05-27 14:34:47', '2026-05-27 14:34:47', 'inherit', NULL, NULL, '[{\"label\":\"Harga pax anak anak\",\"price\":\"9500000\",\"include_travel_cost\":true,\"travel_cost_context\":\"include biaya perjalanan dari jakarta ke bali, untuk biaya ke jakarta di tanggung sendiri. jika mau langsung ke bali sendiri maka biaya bisa dikurangi 2,2 juta\"}]', 1, 'include biaya perjalanan dari jakarta ke bali, untuk biaya ke jakarta di tanggung sendiri. jika mau langsung ke bali sendiri maka biaya bisa dikurangi 2,8 juta');

