INSERT INTO `adv_travel_packages` (`id`, `tenant_id`, `package_type`, `title`, `description`, `price`, `has_sub_items`, `validity_type`, `expiry_date`, `availability_type`, `slot_mode`, `slot_daily`, `slot_weekly`, `slot_monthly`, `slot_yearly`, `slot_total`, `slot_used_total`, `slot_require_admin`, `schedule_enabled`, `departure_description`, `status`, `created_at`, `updated_at`, `ai_summary`, `context_description`, `custom_prices`, `include_travel_cost`, `travel_cost_context`, `transaction_mode`) VALUES
(14, 11, 'private', 'Bali Eksotis & Nusa Penida 3H2M', 'Paket private tour Bali paling lengkap 3 Hari 2 Malam! Jelajahi keindahan Nusa Penida (termasuk tiket snorkeling, kunjungan ke Kelingking Beach, dan Angel Billabong). Trip ini juga termasuk kunjungan ke Uluwatu untuk menonton Kecak Dance saat sunset, dan cultural trip ke Ubud (Tegallalang Rice Terrace & Monkey Forest). Paket ini sangat cocok untuk pasangan, keluarga kecil, atau solo traveler. Harga sudah include penginapan hotel, transportasi mobil AC, dan guide lokal berbahasa Indonesia/Inggris.', 3200000.00, 1, 'expiry_date', '2026-12-31', 'configured', 'configured', 5, NULL, NULL, NULL, 15, 12, 0, 1, NULL, 'active', '2026-05-15 13:23:28', '2026-06-02 21:49:38', 'Konteks ini berisi brosur promosi visual untuk paket \'Bali Eksotis & Nusa Penida 3H2M\', menampilkan keindahan Kelingking Beach di Nusa Penida. Brosur ini merangkum daya tarik utama paket seperti snorkeling, Tari Kecak Uluwatu, dan trip budaya ke Ubud, sekaligus menekankan ketersediaan terbatas. Sangat relevan untuk dikirim kepada pelanggan yang baru mencari paket wisata Bali, ingin melihat gambaran umum destinasi, atau ketika ada kebutuhan untuk mendorong pemesanan dengan urgensi.', 'Brosur Paket Wisata Bali & Nusa Penida', 'null', 0, NULL, 'auto'),
(15, 11, 'private', 'Sunrise Bromo & Kawah Ijen 2H1M (On Request)', 'Paket adventure 2 Hari 1 Malam ke Gunung Bromo dan Kawah Ijen dengan titik keberangkatan dari Surabaya. Hari 1: Penjemputan malam hari menuju Bromo, menikmati sunrise di viewpoint Penanjakan, tour lautan pasir menggunakan Jeep 4WD, dan mendaki ke Kawah Bromo. Hari 2: Perjalanan dilanjutkan dengan trekking malam di Kawah Ijen untuk melihat fenomena blue fire yang sangat langka, lalu kembali ke Surabaya pada pagi hari. Harga sudah termasuk sewa Jeep, tiket masuk semua destinasi wisata, guide lokal, dan penginapan sederhana di area Ijen. Jadwal keberangkatan memerlukan konfirmasi admin terlebih dahulu karena keterbatasan unit Jeep.', 1800000.00, 0, 'always_on', NULL, 'confirmation_required', 'always_ask_admin', NULL, NULL, NULL, NULL, NULL, 0, 0, 1, NULL, 'active', '2026-05-15 13:23:28', '2026-06-01 10:18:44', '', '', 'null', 0, NULL, 'auto'),
(16, 11, 'private', 'Labuan Bajo & Komodo Island 4H3M', 'Eksplorasi surga tersembunyi Indonesia dengan trip Liveaboard 4 Hari 3 Malam di Labuan Bajo. Anda akan tinggal dan berlayar menggunakan kapal phinisi tradisional. Rute pelayaran meliputi: Berangkat dari pelabuhan Labuan Bajo, singgah di Pulau Kelor, melihat komodo langsung di habitat aslinya di Pulau Rinca, trekking menikmati pemandangan di Padar Island, bersantai di pasir merah muda Pink Beach, dan snorkeling bersama pari manta di Manta Point. Paket ini menawarkan 3 opsi akomodasi: Backpacker (kabin bersama), Premium (kabin privat untuk pasangan), dan Exclusive (sewa 1 kapal penuh untuk rombongan).', 0.00, 1, 'expiry_date', '2027-03-31', 'always', 'always_ready', NULL, NULL, NULL, NULL, NULL, 0, 0, 1, NULL, 'active', '2026-05-15 13:23:28', '2026-06-01 10:19:04', '', '', 'null', 0, NULL, 'auto'),
(17, 11, 'others', 'Sewa Motor Harian Bali', 'Layanan penyewaan sepeda motor harian di area Pulau Bali. Menawarkan berbagai unit motor matic populer seperti Honda Vario, PCX, dan Yamaha NMAX yang dirawat secara berkala. Setiap penyewaan unit sudah termasuk: 2 buah helm SNI, 2 pasang jas hujan ponco, dan STNK kendaraan asli. Syarat penyewaan sangat mudah: cukup titipkan identitas asli (KTP/Paspor) dan wajib memiliki SIM C. Kami melayani antar-jemput motor gratis (free delivery) ke hotel/villa Anda khusus di area Kuta, Seminyak, dan Legian. Minimal durasi sewa adalah 1 hari (24 jam), dan kami memberikan diskon khusus 10% untuk penyewaan selama 7 hari atau lebih.', 75000.00, 1, 'always_on', NULL, 'always', 'configured', 10, NULL, NULL, NULL, NULL, 0, 0, 1, NULL, 'active', '2026-05-15 13:23:28', '2026-05-15 13:23:28', '', '', NULL, 0, NULL, 'auto');

