  `id` int(10) UNSIGNED NOT NULL,
  `tenant_id` int(10) UNSIGNED NOT NULL,
  `phone` varchar(50) NOT NULL,
  `customer_name` varchar(255) DEFAULT NULL,
  `service_label` varchar(100) DEFAULT NULL,
  `schedule_date` date DEFAULT NULL,
  `schedule_time` varchar(20) DEFAULT NULL,
  `duration_minutes` int(11) DEFAULT 60,
  `schedule_id` int(10) UNSIGNED DEFAULT NULL,
  `session_id` varchar(100) DEFAULT NULL,
  `status` enum('pending','active','inactive','approved','rejected','canceled','completed','generated','done','canceled_customer','pending_customer','approved_with_terms','taken_over','waiting_offer','waiting_date','waiting_payment','confirmed','on_trip','overdue','returned','retired','processing','shipped','paid','sign','expired','2nd_pending') DEFAULT 'active',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

