CREATE TABLE `email_messages` (
  `id` int(10) UNSIGNED NOT NULL,
  `tenant_id` int(10) UNSIGNED NOT NULL,
  `message_id` varchar(500) NOT NULL,
  `thread_id` varchar(500) DEFAULT NULL,
