CREATE TABLE `leads` (
  `id` int(10) UNSIGNED NOT NULL,
  `tenant_id` int(10) UNSIGNED NOT NULL,
  `phone` varchar(50) NOT NULL,
  `push_name` varchar(255) DEFAULT NULL,
  `saved_name` varchar(255) DEFAULT NULL,
  `status` enum('baru','follow_up','closing','closed','failed','potensial','not_potensial','menunggu_pembayaran','komplain','selesai','batal','lunas','cancelled','customer') DEFAULT 'baru',
  `label` enum('potensial','hot','member','cold','customer') DEFAULT 'potensial',
